1	import { NextResponse } from 'next/server';
2	import { ZodError } from 'zod';
3	import type { ApiError, ApiErrorCode } from '@/contracts/api';
4	import {
5	  ConflictError,
6	  NotFoundError,
7	  RateLimitedError,
8	  UnauthorizedError,
9	  UnprocessableError,
10	} from './errors';
11	
12	const STATUS_BY_CODE: Record<ApiErrorCode, number> = {
13	  UNAUTHORIZED: 401,
14	  BAD_REQUEST: 400,
15	  NOT_FOUND: 404,
16	  CONFLICT: 409,
17	  RATE_LIMITED: 429,
18	  UPSTREAM_UNAVAILABLE: 502,
19	  UNPROCESSABLE: 422,
20	  PAYLOAD_TOO_LARGE: 413,
21	  INTERNAL: 500,
22	};
23	
24	const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
25	/** Path ids go straight into SQL; a malformed one should be a 404, not a Postgres 500. */
26	export const isUuid = (id: string) => uuid.test(id);
27	
28	export function jsonOk<T>(data: T, init?: ResponseInit) {
29	  return NextResponse.json(data, init);
30	}
31	
32	export function jsonError(code: ApiErrorCode, message: string, details?: unknown): NextResponse<ApiError> {
33	  return NextResponse.json({ error: { code, message, details } }, { status: STATUS_BY_CODE[code] });
34	}
35	
36	export function jsonErrorFromZod(error: ZodError): NextResponse<ApiError> {
37	  return jsonError('BAD_REQUEST', 'Validation failed', error.flatten());
38	}
39	
40	/** Converts a thrown error into the right typed ApiError response. Catch-all for route handlers. */
41	export function handleRouteError(err: unknown): NextResponse<ApiError> {
42	  if (err instanceof UnauthorizedError) return jsonError('UNAUTHORIZED', err.message || 'Not signed in');
43	  if (err instanceof NotFoundError) return jsonError('NOT_FOUND', err.message || 'Not found');
44	  if (err instanceof ConflictError) return jsonError('CONFLICT', err.message || 'Conflict');
45	  if (err instanceof UnprocessableError) return jsonError('UNPROCESSABLE', err.message, err.details);
46	  if (err instanceof RateLimitedError) {
47	    const res = jsonError('RATE_LIMITED', err.message || 'Too many requests');
48	    res.headers.set('Retry-After', String(Math.ceil(err.retryAfterMs / 1000)));
49	    return res;
50	  }
51	  if (err instanceof ZodError) return jsonErrorFromZod(err);
52	  console.error(err);
53	  return jsonError('INTERNAL', 'Something went wrong');
54	}
55	
56	/**
57	 * Streams one JSON object per line as `application/x-ndjson`. `producer`
58	 * receives a `write` callback and should await every upstream step before
59	 * writing the matching event, so clients see progress instead of one
60	 * buffered burst at the end.
61	 */
62	export function ndjsonResponse<T>(
63	  producer: (write: (event: T) => void, signal: AbortSignal) => Promise<void>,
64	): Response {
65	  const encoder = new TextEncoder();
66	  // Aborted when the client goes away (e.g. a new search replaces this one): writes become
67	  // no-ops and producers should stop starting new upstream work.
68	  const abort = new AbortController();
69	  const stream = new ReadableStream<Uint8Array>({
70	    async start(controller) {
71	      const write = (event: T) => {
72	        if (abort.signal.aborted) return;
73	        try {
74	          controller.enqueue(encoder.encode(`${JSON.stringify(event)}\n`));
75	        } catch {
76	          abort.abort();
77	        }
78	      };
79	      try {
80	        await producer(write, abort.signal);
81	      } catch (err) {
82	        write({
83	          type: 'error',
84	          error: { code: 'INTERNAL', message: err instanceof Error ? err.message : 'Unknown error' },
85	        } as T);
86	      } finally {
87	        if (!abort.signal.aborted) controller.close();
88	      }
89	    },
90	    cancel() {
91	      abort.abort();
92	    },
93	  });
94	  return new Response(stream, {
95	    headers: {
96	      'Content-Type': 'application/x-ndjson; charset=utf-8',
97	      'Cache-Control': 'no-cache',
98	      'X-Content-Type-Options': 'nosniff',
99	    },
100	  });
101	}
