15	interface UserRow {
16	  id: string;
17	  auth0_sub: string;
18	  email: string | null;
19	  display_name: string | null;
20	  avatar_url: string | null;
21	  tz: string;
22	}
23	
24	/** Local dev without Auth0 (see `authDisabled`); same id as main's old placeholder. */
25	const DEV_USER: AppUser = {
26	  id: '00000000-0000-4000-8000-000000000001',
27	  auth0Sub: 'dev|local',
28	  email: 'demo@mise.local',
29	  displayName: 'Demo cook',
30	  avatarUrl: null,
31	  tz: 'America/Vancouver',
32	};
33	
34	/** With a database but no Auth0, make sure the demo user's row exists (FKs on recipes, sessions, …). Once per process. */
35	let devUserSeeded: Promise<void> | null = null;
36	function ensureDevUser(): Promise<void> {
37	  if (!process.env.DATABASE_URL) return Promise.resolve(); // no DB: fixture-only local dev
38	  devUserSeeded ??= sql`
39	    INSERT INTO users (id, auth0_sub, email, display_name, tz)
40	    VALUES (${DEV_USER.id}, ${DEV_USER.auth0Sub}, ${DEV_USER.email}, ${DEV_USER.displayName}, ${DEV_USER.tz})
41	    ON CONFLICT DO NOTHING
42	  `.then(
43	    () => undefined,
44	    (err) => {
45	      devUserSeeded = null; // retry on the next request
46	      throw err;
47	    },
48	  );
49	  return devUserSeeded;
50	}
51	
52	/**
53	 * First line of every route handler (SPEC.md §7). Upserts the Auth0 session's
54	 * `sub` into `users` (never merges by email — SPEC.md §5.2) and returns our
55	 * own user row. Throws UnauthorizedError, caught by `handleRouteError`.
56	 */
57	export async function requireUser(): Promise<AppUser> {
58	  if (authDisabled) {
59	    await ensureDevUser();
60	    return DEV_USER;
61	  }
62	  const session = await auth0.getSession();
63	  if (!session) throw new UnauthorizedError('No active session');
64	
65	  const rows = await sql<UserRow[]>`
66	    INSERT INTO users (auth0_sub, email, display_name, avatar_url)
67	    VALUES (${session.user.sub}, ${session.user.email ?? null}, ${session.user.name ?? null}, ${session.user.picture ?? null})
68	    ON CONFLICT (auth0_sub) DO UPDATE SET
69	      last_seen_at = now(),
70	      email = COALESCE(EXCLUDED.email, users.email),
71	      display_name = COALESCE(users.display_name, EXCLUDED.display_name),
72	      avatar_url = COALESCE(users.avatar_url, EXCLUDED.avatar_url)
73	    RETURNING id, auth0_sub, email, display_name, avatar_url, tz
74	  `;
75	  const row = rows[0];
76	  if (!row) throw new Error('requireUser: upsert returned no row');
77	
78	  return {
79	    id: row.id,
80	    auth0Sub: row.auth0_sub,
81	    email: row.email,
82	    displayName: row.display_name,
83	    avatarUrl: row.avatar_url,
84	    tz: row.tz,
85	  };
86	}
