9	export async function GET(request: Request) {
10	  try {
11	    const user = await requireUser();
12	    const date = new URL(request.url).searchParams.get('date') ?? todayInTz(user.tz);
13	    if (!isIsoDate(date)) return jsonError('BAD_REQUEST', 'date must be YYYY-MM-DD');
14	    return jsonOk({ meals: await listMeals(user.id, date) });
15	  } catch (err) {
16	    return handleRouteError(err);
17	  }
18	}
