20	export async function POST(request: Request) {
21	  try {
22	    const user = await requireUser();
23	    const parsed = manualMealSchema.safeParse(await request.json().catch(() => null));
24	    if (!parsed.success) return jsonErrorFromZod(parsed.error);
25	    return jsonOk(await logMeal(user, parsed.data as ManualMealRequest), { status: 201 });
26	  } catch (err) {
27	    return handleRouteError(err);
28	  }
