48	export async function getProfile(userId: string): Promise<UserProfile> {
49	  const [row] = await sql<UserRow[]>`SELECT ${columns()} FROM users WHERE id = ${userId}`;
50	  if (!row) throw new NotFoundError('User not found');
51	  return rowToProfile(row);
52	}
