54	export async function updateProfile(userId: string, patch: UpdateMeInput): Promise<UserProfile> {
55	  const set: Record<string, unknown> = {};
56	  if (patch.displayName !== undefined) set.display_name = patch.displayName;
57	  if (patch.tz !== undefined) set.tz = patch.tz;
58	  if (patch.dailyKcalGoal !== undefined) set.daily_kcal_goal = patch.dailyKcalGoal;
59	  if (patch.dailyProteinGoalG !== undefined) set.daily_protein_goal_g = patch.dailyProteinGoalG;
60	  if (patch.diets !== undefined) set.diets = patch.diets;
61	  if (patch.allergens !== undefined) set.allergens = patch.allergens;
62	  if (patch.pastBestBeforeGraceDays !== undefined) set.past_best_before_grace_days = patch.pastBestBeforeGraceDays;
63	
64	  const keys = Object.keys(set);
65	  const onboard = patch.completeOnboarding === true;
66	  if (keys.length === 0 && !onboard) return getProfile(userId);
67	
68	  const onboardedAt = onboard ? sql`COALESCE(onboarded_at, now())` : sql`onboarded_at`;
69	  const [row] = keys.length
70	    ? await sql<UserRow[]>`
71	        UPDATE users SET ${sql(set, keys)}, onboarded_at = ${onboardedAt}
72	        WHERE id = ${userId} RETURNING ${columns()}`
73	    : await sql<UserRow[]>`
74	        UPDATE users SET onboarded_at = ${onboardedAt}
75	        WHERE id = ${userId} RETURNING ${columns()}`;
76	  if (!row) throw new NotFoundError('User not found');
77	  return rowToProfile(row);
78	}
