15	const schema = z.object({
16	  AUTH0_DOMAIN: z.string().min(1),
17	  AUTH0_CLIENT_ID: z.string().min(1),
18	  AUTH0_CLIENT_SECRET: z.string().min(1),
19	  AUTH0_SECRET: z.string().min(32, 'must be at least 32 characters (openssl rand -hex 32)'),
20	  APP_BASE_URL: z.string().url().optional(),
21	
22	  DATABASE_URL: z.string().regex(PG_URL, 'must be a postgres:// connection string'),
23	  DB_POOL_MAX: z.coerce.number().int().positive().default(5),
24	  DATABASE_URL_TEST: z.string().regex(PG_URL, 'must be a postgres:// connection string').optional(),
25	
26	  GOOGLE_CLOUD_PROJECT: z.string().min(1),
27	  GOOGLE_CLOUD_LOCATION: z.string().min(1).catch('us-central1'), // blank line in .env also falls back
28	  GEMINI_MODEL: z.string().default('gemini-3.8-flash'),
29	  GEMINI_SEARCH_MODEL: z.string().default('gemini-3.8-flash'),
30	
31	  DATAANDAPIS_KEY: z.string().min(1),
32	  OFF_BASE_URL: z.string().url().default('https://world.openfoodfacts.org'),
33	  OFF_USER_AGENT: z.string().min(1),
34	  RECIPE_FETCH_USER_AGENT: z.string().min(1),
35	
36	  ELEVENLABS_API_KEY: z.string().optional(),
37	  ELEVENLABS_VOICE_ID: z.string().default('JBFqnCBsd6RMkjVDRZzb'),
38	  ELEVENLABS_MODEL_ID: z.string().default('eleven_flash_v2_5'),
39	
40	  DEFAULT_TZ: z.string().refine(isValidTimeZone, 'must be an IANA time zone').default('America/Vancouver'),
41	});
42	
43	type Env = z.infer<typeof schema>;
44	
45	let cached: Env | null = null;
46	
47	/**
48	 * Validates server env vars with Zod and fails fast. Skipped during `vitest`
49	 * (NODE_ENV=test) so pure unit tests don't need every production secret —
50	 * anything that actually calls an external API should mock its own env reads.
51	 */
52	export function getEnv(): Env {
53	  if (cached) return cached;
54	  // `KEY=` (empty, as in .env.example) means unset, not an invalid empty string.
55	  const source = Object.fromEntries(Object.entries(process.env).filter(([, v]) => v !== undefined && v.trim() !== ''));
56	  // `next build` imports route modules without runtime secrets; validate at request time instead.
57	  if (process.env.NODE_ENV === 'test' || process.env.NEXT_PHASE === 'phase-production-build') {
58	    cached = schema.partial().parse(source) as Env;
59	    return cached;
60	  }
61	  const parsed = schema.safeParse(source);
62	  if (!parsed.success && process.env.NODE_ENV !== 'production') {
63	    // Local dev without every key: warn and run; features needing a missing key fail on use.
64	    console.warn('[env] missing env vars (dev only, not fatal):', Object.keys(parsed.error.flatten().fieldErrors).join(', '));
65	    cached = schema.partial().parse(source) as Env;
66	    return cached;
67	  }
68	  if (!parsed.success) {
69	    console.error('[env] invalid/missing environment variables:', parsed.error.flatten().fieldErrors);
70	    throw new Error('Invalid environment configuration — see logs above.');
71	  }
72	  if (process.env.NODE_ENV === 'production' && !parsed.data.APP_BASE_URL) {
73	    console.error('[env] invalid/missing environment variables: { APP_BASE_URL: [ "is required in production" ] }');
74	    throw new Error('Invalid environment configuration — see logs above.');
75	  }
76	  cached = parsed.data;
77	  return cached;
78	}
