1	import type { DisplayUnit, Nutrients, UnitDim } from '@/contracts/domain';
2	import { DISPLAY_UNITS, convertBetween, toBase, unitDim } from '@/lib/units';
3	
4	// SPEC F15: turning "170 g of this item" into calories, and into a pantry deduction. Pure, so the
5	// Log Food preview and the server always agree.
6	
7	export interface FoodSource {
8	  basis: '100g' | '100ml' | 'unit';
9	  nutrition: Nutrients;
10	  /** What the stock is measured in; null for a product that isn't in the pantry. */
11	  stockDim: UnitDim | null;
12	  gramsPerUnit: number | null;
13	  densityGPerMl: number | null;
14	}
15	
16	export interface MealNutrition {
17	  kcal: number;
18	  proteinG: number;
19	  carbsG: number | null;
20	  fatG: number | null;
21	}
22	
23	export type AmountResult = { ok: true; meal: MealNutrition } | { ok: false; reason: 'invalid_amount' | 'no_calories' | 'no_conversion' };
24	
25	const BASIS: Record<FoodSource['basis'], { dim: UnitDim; per: number }> = {
26	  '100g': { dim: 'mass', per: 100 },
27	  '100ml': { dim: 'volume', per: 100 },
28	  unit: { dim: 'count', per: 1 },
29	};
30	
31	const oneDecimal = (n: number) => Math.round((n + Number.EPSILON) * 10) / 10;
32	
33	function convert(source: FoodSource, amount: number, unit: DisplayUnit, to: UnitDim): number | null {
34	  const base = toBase(amount, unit);
35	  return base ? convertBetween(base.qtyBase, base.dim, to, source) : null;
36	}
37	
38	/** The amount in the stock's base unit, or null when it can't be converted. */
39	export function amountInStock(source: FoodSource, amount: number, unit: DisplayUnit): number | null {
40	  return source.stockDim ? convert(source, amount, unit, source.stockDim) : null;
41	}
42	
43	export function nutritionForAmount(source: FoodSource, amount: number, unit: DisplayUnit): AmountResult {
44	  if (!Number.isFinite(amount) || amount <= 0) return { ok: false, reason: 'invalid_amount' };
45	  // Team decision: no calorie data blocks logging, so totals never silently undercount.
46	  const kcalPer = source.nutrition.energyKcal;
47	  if (kcalPer == null) return { ok: false, reason: 'no_calories' };
48	  const { dim, per } = BASIS[source.basis];
49	  const inBasis = convert(source, amount, unit, dim);
50	  if (inBasis === null) return { ok: false, reason: 'no_conversion' };
51	  const factor = inBasis / per;
52	  const scaled = (v: number | null | undefined) => (v == null ? null : oneDecimal(v * factor));
53	  return {
54	    ok: true,
55	    meal: {
56	      kcal: oneDecimal(kcalPer * factor),
57	      proteinG: scaled(source.nutrition.proteinG) ?? 0,
58	      carbsG: scaled(source.nutrition.carbohydrateG),
59	      fatG: scaled(source.nutrition.fatG),
60	    },
61	  };
62	}
63	
64	/** Units this food can be logged in: convertible to its nutrition basis and to its stock. */
65	export function loggableUnits(source: FoodSource): DisplayUnit[] {
66	  const basisDim = BASIS[source.basis].dim;
67	  return DISPLAY_UNITS.filter((u) => {
68	    const dim = unitDim(u);
69	    if (convertBetween(1, dim, basisDim, source) === null) return false;
70	    return source.stockDim === null || convertBetween(1, dim, source.stockDim, source) !== null;
71	  });
72	}
73	
74	export function amountError(reason: Exclude<AmountResult, { ok: true }>['reason']): string {
75	  if (reason === 'no_calories') return 'This item has no calorie data. Add it on the Pantry page, or use Quick add.';
76	  if (reason === 'no_conversion') return "We can't convert that unit for this item.";
77	  return 'Enter an amount greater than 0.';
78	}
