7	// SPEC F15: daily calories for the last 7 days, with the goal as a reference line. One series, so
8	// the card title names it and there's no legend. Protein is in the tooltip and the table.
9	
10	const HEIGHT = 200;
11	const MARGIN = { top: 20, right: 8, bottom: 24, left: 44 };
12	const MAX_COLUMN = 24;
13	const INITIAL_WIDTH = 560;
14	
15	export function WeekChart({ days }: { days: DailyTotals[] }) {
16	  const boxRef = useRef<HTMLDivElement>(null);
17	  const [width, setWidth] = useState(INITIAL_WIDTH);
18	  const [active, setActive] = useState<number | null>(null);
19	
20	  useEffect(() => {
21	    const box = boxRef.current;
22	    if (!box) return;
23	    const observer = new ResizeObserver(([entry]) => setWidth(Math.max(240, entry.contentRect.width)));
24	    observer.observe(box);
25	    return () => observer.disconnect();
26	  }, []);
27	
28	  if (days.every((d) => d.entries === 0)) {
29	    return <p className="py-10 text-center text-sm text-muted">Log some food to see your week here.</p>;
30	  }
31	
32	  const goal = days.at(-1)?.kcalGoal ?? null;
33	  const top = niceCeil(Math.max(...days.map((d) => d.kcal), goal ?? 0));
34	  const plotWidth = width - MARGIN.left - MARGIN.right;
35	  const baseline = HEIGHT - MARGIN.bottom;
36	  const plotHeight = baseline - MARGIN.top;
37	  const band = plotWidth / days.length;
38	  const column = Math.min(MAX_COLUMN, band * 0.6);
39	  const y = (v: number) => baseline - (v / top) * plotHeight;
40	  const centerX = (i: number) => MARGIN.left + band * i + band / 2;
41	  const lastIndex = days.length - 1;
42	  const shown = active === null ? null : days[active];
43	  const dayName = (i: number) => (i === lastIndex ? 'Today' : weekdayLabel(days[i].date));
44	
45	  return (
46	    <div>
47	      <div ref={boxRef} className="relative">
48	        <svg width={width} height={HEIGHT} className="block max-w-full" role="group" aria-label="Calories per day, last 7 days">
49	          {[0, top / 2, top].map((tick) => (
50	            <g key={tick}>
51	              <line x1={MARGIN.left} x2={width - MARGIN.right} y1={y(tick)} y2={y(tick)} stroke="var(--line)" strokeWidth={1} />
52	              <text x={MARGIN.left - 8} y={y(tick) + 4} textAnchor="end" fontSize={12} fill="var(--muted)">
53	                {tick}
54	              </text>
55	            </g>
56	          ))}
57	
58	          {days.map((d, i) =>
59	            d.kcal > 0 ? (
60	              <path
61	                key={d.date}
62	                d={columnPath(centerX(i) - column / 2, baseline, column, Math.max(2, baseline - y(d.kcal)))}
63	                fill={CHART_COLOR}
64	                opacity={active === null || active === i ? 1 : 0.55}
65	              />
66	            ) : null,
67	          )}
68	
69	          {goal != null && (
70	            <g>
71	              <line x1={MARGIN.left} x2={width - MARGIN.right} y1={y(goal)} y2={y(goal)} stroke="var(--ink)" strokeWidth={1.5} strokeDasharray="4 4" />
72	              <text x={width - MARGIN.right} y={y(goal) - 5} textAnchor="end" fontSize={12} fill="var(--ink)">
73	                Goal {goal}
74	              </text>
75	            </g>
76	          )}
77	
78	          {days[lastIndex].kcal > 0 && (
79	            <text x={centerX(lastIndex)} y={y(days[lastIndex].kcal) - 5} textAnchor="middle" fontSize={12} fontWeight={600} fill="var(--ink)">
80	              {Math.round(days[lastIndex].kcal)}
81	            </text>
82	          )}
83	
84	          {days.map((d, i) => (
85	            <text key={d.date} x={centerX(i)} y={HEIGHT - 6} textAnchor="middle" fontSize={12} fontWeight={i === lastIndex ? 600 : 400} fill={i === lastIndex ? 'var(--ink)' : 'var(--muted)'}>
86	              {dayName(i)}
87	            </text>
88	          ))}
89	
90	          {days.map((d, i) => (
91	            <rect
92	              key={d.date}
93	              x={MARGIN.left + band * i}
94	              y={MARGIN.top}
95	              width={band}
96	              height={plotHeight + MARGIN.bottom}
97	              fill="transparent"
98	              tabIndex={0}
99	              role="img"
100	              aria-label={`${dayName(i)}: ${Math.round(d.kcal)} kcal, ${Math.round(d.proteinG)} g protein`}
101	              className="outline-none focus-visible:stroke-[var(--ink)]"
102	              onMouseEnter={() => setActive(i)}
103	              onMouseLeave={() => setActive(null)}
104	              onFocus={() => setActive(i)}
105	              onBlur={() => setActive(null)}
106	            />
107	          ))}
108	        </svg>
109	
110	        {shown && active !== null && (
111	          <div
112	            role="status"
113	            className="pointer-events-none absolute top-0 whitespace-nowrap rounded-lg border border-line bg-surface px-2.5 py-1.5 text-xs shadow-sm"
114	            style={{ left: Math.min(Math.max(centerX(active) - 56, 0), width - 128) }}
115	          >
116	            <p className="font-semibold">{dayName(active)}</p>
117	            <p className="tabular-nums">
118	              {Math.round(shown.kcal)} kcal · {Math.round(shown.proteinG)} g protein
119	            </p>
120	          </div>
121	        )}
122	      </div>
123	
124	      <details className="mt-2 text-sm">
125	        <summary className="cursor-pointer text-muted">View as table</summary>
126	        <table className="mt-2 w-full text-left tabular-nums">
127	          <thead>
128	            <tr className="text-muted">
129	              <th className="py-1 font-medium">Day</th>
130	              <th className="py-1 font-medium">Calories</th>
131	              <th className="py-1 font-medium">Protein</th>
132	            </tr>
133	          </thead>
134	          <tbody>
135	            {days.map((d, i) => (
136	              <tr key={d.date} className="border-t border-line">
137	                <td className="py-1">{dayName(i)}</td>
138	                <td className="py-1">{Math.round(d.kcal)} kcal</td>
139	                <td className="py-1">{Math.round(d.proteinG)} g</td>
140	              </tr>
141	            ))}
142	          </tbody>
143	        </table>
144	      </details>
145	    </div>
146	  );
147	}
