20	export function isValidTimeZone(tz: string): boolean {
21	  try {
22	    new Intl.DateTimeFormat('en-US', { timeZone: tz });
23	    return true;
24	  } catch {
25	    return false;
26	  }
27	}
28	
29	/** Unique values, order kept. */
30	const uniq = <T>(xs: T[]) => [...new Set(xs)];
31	
32	export const updateMeSchema = z
33	  .object({
34	    displayName: z.string().trim().min(1).max(80).optional(),
35	    tz: z.string().refine(isValidTimeZone, 'must be an IANA time zone').optional(),
36	    dailyKcalGoal: z.number().int().min(1).max(20_000).nullable().optional(),
37	    dailyProteinGoalG: z.number().finite().min(0).max(1_000).nullable().optional(),
38	    diets: z.array(dietFlag).max(DIET_FLAGS.length).transform(uniq).optional(),
39	    allergens: z.array(allergen).max(ALL_ALLERGENS.length).transform(uniq).optional(),
40	    pastBestBeforeGraceDays: z.number().int().min(0).max(14).optional(),
41	    completeOnboarding: z.boolean().optional(),
42	  })
43	  .strict();
44	
45	const nutrients = z
46	  .object({
47	    energyKcal: nonNegative.nullable(),
48	    proteinG: nonNegative.nullable(),
49	    carbohydrateG: nonNegative.nullable(),
50	    fatG: nonNegative.nullable(),
51	    saturatedFatG: nonNegative.nullable().optional(),
52	    sugarsG: nonNegative.nullable().optional(),
53	    fibreG: nonNegative.nullable().optional(),
54	    sodiumMg: nonNegative.nullable().optional(),
55	  })
56	  .strict();
57	
58	const NAME_MAX = 120;
59	
60	const pantryFields = {
61	  name: z.string().trim().min(1, 'name is required').max(NAME_MAX),
62	  brand: z.string().trim().max(NAME_MAX).nullable().optional(),
63	  quantity: nonNegative,
64	  displayUnit,
65	  gramsPerUnit: positive.max(100_000).nullable().optional(),
66	  densityGPerMl: positive.max(25).nullable().optional(),
67	  expiryDate: isoDate.nullable().optional(),
68	  expirySource: z.enum(['photo', 'manual']).nullable().optional(),
69	  expiryRawText: z.string().trim().max(200).nullable().optional(),
70	  nutritionBasis: z.enum(['100g', '100ml', 'unit']),
71	  nutrition: nutrients.nullable().optional(),
72	  servingSizeBase: positive.max(100_000).nullable().optional(),
73	  allergenTags: z.array(allergen).max(ALL_ALLERGENS.length).optional(),
74	  userVerified: z.boolean(),
75	};
76	
77	/** expiry_date and expiry_source are both set or both null (DB CHECK). */
78	function expiryConsistent(v: { expiryDate?: string | null; expirySource?: string | null }) {
79	  if (v.expiryDate === undefined && v.expirySource === undefined) return true;
80	  return (v.expiryDate ?? null) === null ? (v.expirySource ?? null) === null : (v.expirySource ?? null) !== null;
81	}
