94	export const updatePantryItemSchema = z
95	  .object({
96	    ...Object.fromEntries(Object.entries(pantryFields).map(([k, v]) => [k, v.optional()])),
97	    adjustReason: z.enum(['manual_adjust', 'discard']).optional(),
98	  } as { [K in keyof typeof pantryFields]: z.ZodOptional<(typeof pantryFields)[K]> } & {
99	    adjustReason: z.ZodOptional<z.ZodEnum<{ manual_adjust: 'manual_adjust'; discard: 'discard' }>>;
100	  })
101	  .strict()
102	  .refine(expiryConsistent, EXPIRY_MSG)
