138	              item={item}
139	              graceDays={graceDays}
140	              onAdjust={(quantity) => run(() => pantryApi.update(item.id, { quantity, adjustReason: 'manual_adjust' }), `Updated ${item.name}`)}
141	              onDiscard={() => run(() => pantryApi.update(item.id, { adjustReason: 'discard' }), `Discarded ${item.name}`)}
142	              onRestock={() => run(() => pantryApi.restock(item.id), `Restocked ${item.name}`)}
143	              onEdit={() => setEditing(item)}
144	              onDelete={() => setDeleting(item)}
