156	          <ProductForm
157	            key={editing.id}
158	            initial={{
159	              ...editing,
160	              quantity: fromBase(editing.quantityBase, editing.dim, editing.displayUnit),
161	              expiryRawText: null,
162	            }}
163	            submitLabel="Save changes"
164	            onSubmit={(v) => saveEdit(editing, v)}
