183	                }}
184	              >
185	                Delete
186	              </Button>
187	              <Button variant="secondary" onClick={() => setDeleting(null)}>
188	                Cancel
189	              </Button>
190	            </div>
191	          </div>
192	        )}
193	      </Dialog>
194	    </div>
195	  );
196	}
