198	function PantryRow({
199	  item,
200	  graceDays,
201	  onAdjust,
202	  onDiscard,
203	  onRestock,
204	  onEdit,
205	  onDelete,
206	}: {
207	  item: PantryItem;
208	  graceDays: number;
209	  onAdjust: (quantity: number) => Promise<void>;
210	  onDiscard: () => Promise<void>;
211	  onRestock: () => Promise<void>;
212	  onEdit: () => void;
213	  onDelete: () => void;
214	}) {
215	  const info = expiryInfo(item.expiryDate, item.daysToExpiry, graceDays);
216	  const band = BAND_CLASSES[info.band];
217	  const empty = item.quantityBase <= 0;
218	  const current = fromBase(item.quantityBase, item.dim, item.displayUnit) ?? 0;
219	  const [adjusting, setAdjusting] = useState(false);
220	  const [value, setValue] = useState(String(Math.round(current * 100) / 100));
221	  const nutrition = itemNutritionLines(item);
222	
223	  return (
224	    <li className="relative overflow-hidden rounded-2xl border border-line bg-surface">
225	      <span aria-hidden className={`absolute inset-y-0 left-0 w-1.5 ${band.stripe}`} />
226	      <div className="grid gap-2 py-4 pl-5 pr-4">
227	        <div className="flex flex-wrap items-start gap-x-3 gap-y-1">
228	          <div className="min-w-0 flex-1">
229	            <p className="font-semibold">
230	              {item.name}
231	              {item.brand && <span className="font-normal text-muted"> · {item.brand}</span>}
232	            </p>
233	            <p className="text-sm">
234	              {empty ? <span className="font-semibold text-muted">Empty</span> : item.quantityDisplay}
235	            </p>
236	          </div>
237	          <span className={`rounded-full px-2.5 py-0.5 text-xs font-semibold ${band.badge}`}>{info.text}</span>
238	        </div>
239	
240	        {nutrition.map((line) => (
241	          <p key={line} className="text-xs text-muted">
242	            {line}
243	          </p>
244	        ))}
245	        {item.allergenTags.length > 0 && (
246	          <div className="flex flex-wrap gap-1">
247	            {item.allergenTags.map((a) => (
248	              <Badge key={a}>Contains {ALLERGEN_LABELS[a].split(' (')[0].toLowerCase()}</Badge>
249	            ))}
250	          </div>
251	        )}
252	        {(item.source === 'openfoodfacts' || item.source === 'dataandapis') && (
253	          <p className="text-xs text-muted">Product data: Open Food Facts (ODbL)</p>
254	        )}
255	
256	        {adjusting ? (
257	          <form
258	            className="flex flex-wrap items-center gap-2"
259	            onSubmit={async (e) => {
260	              e.preventDefault();
261	              const q = Number(value.replace(',', '.'));
262	              if (!Number.isFinite(q) || q < 0) return;
263	              await onAdjust(q);
264	              setAdjusting(false);
265	            }}
266	          >
267	            <label className="flex items-center gap-2 text-sm">
268	              Now have
269	              <input
270	                className="min-h-11 w-28 rounded-xl border border-line bg-surface px-3"
271	                inputMode="decimal"
272	                value={value}
273	                onChange={(e) => setValue(e.target.value)}
274	                autoFocus
275	              />
276	              {UNIT_LABELS[item.displayUnit]}
277	            </label>
278	            <Button type="submit">Save</Button>
279	            <Button variant="ghost" onClick={() => setAdjusting(false)}>
280	              Cancel
281	            </Button>
282	          </form>
283	        ) : (
284	          <div className="flex flex-wrap gap-2">
285	            {empty ? (
286	              <Button variant="secondary" onClick={() => void onRestock()}>
287	                Restock
288	              </Button>
289	            ) : (
290	              <>
291	                <Button variant="secondary" onClick={() => setAdjusting(true)}>
292	                  Adjust
293	                </Button>
294	                <Button variant="secondary" onClick={() => void onDiscard()}>
295	                  Discard
296	                </Button>
297	              </>
298	            )}
299	            <Button variant="ghost" onClick={onEdit}>
300	              Edit
301	            </Button>
302	            <Button variant="ghost" onClick={onDelete}>
303	              Delete
304	            </Button>
305	          </div>
306	        )}
307	      </div>
308	    </li>
309	  );
310	}
