50	const str = (n: number | null | undefined) => (n == null ? '' : String(n));
51	/** '' → null; otherwise a finite number ≥ 0, or NaN for invalid input. */
52	function parseNum(s: string): number | null {
53	  const t = s.trim().replace(',', '.');
54	  if (t === '') return null;
55	  const n = Number(t);
56	  return Number.isFinite(n) && n >= 0 ? n : Number.NaN;
