117	    if (q === null || Number.isNaN(q) || q <= 0) return setError('Enter a quantity greater than 0.');
118	    if (hasExpiry && !/^\d{4}-\d{2}-\d{2}$/.test(expiryDate)) return setError('Pick a best-before date, or choose "No date".');
119	
120	    const nums = Object.fromEntries(NUTRIENT_FIELDS.map((f) => [f.key, parseNum(nutrients[f.key] ?? '')])) as Record<
121	      (typeof NUTRIENT_FIELDS)[number]['key'],
