273	            </label>
274	          ))}
275	        </div>
276	        {basis !== 'unit' && (
277	          <label className="grid max-w-xs gap-1 text-sm">
278	            Serving size ({basis === '100ml' ? 'ml' : 'g'}) <span className="text-muted">optional</span>
279	            <input
280	              className={inputClass(flagged.has('servingSize'))}
281	              inputMode="decimal"
282	              value={servingSize}
283	              onChange={(e) => setServingSize(e.target.value)}
284	            />
285	          </label>
286	        )}
287	      </fieldset>
288	
289	      <fieldset>
290	        <legend className="mb-2 text-sm font-semibold">Contains allergens</legend>
291	        <div className="flex flex-wrap gap-2">
292	          {ALLERGENS.map((a) => (
293	            <label
294	              key={a}
295	              className={`flex min-h-11 cursor-pointer items-center gap-2 rounded-full border px-3 text-sm ${
