298	            >
299	              <input type="checkbox" className="sr-only" checked={allergens.includes(a)} onChange={() => toggleAllergen(a)} />
300	              <span aria-hidden>{allergens.includes(a) ? '✓' : '+'}</span> {ALLERGEN_LABELS[a]}
301	            </label>
302	          ))}
303	        </div>
304	        <p className="mt-2 text-xs text-muted">Always check product labels for allergens.</p>
305	      </fieldset>
306	
307	      {error && (
308	        <p role="alert" className="rounded-xl bg-danger-soft px-3 py-2 text-sm text-danger">
309	          {error}
310	        </p>
311	      )}
312	      <div className="flex flex-wrap gap-3">
313	        <Button type="submit" disabled={saving}>
314	          {saving ? 'Saving…' : submitLabel}
315	        </Button>
316	        {onCancel && (
317	          <Button variant="secondary" onClick={onCancel} disabled={saving}>
318	            Cancel
319	          </Button>
320	        )}
321	      </div>
322	    </form>
323	  );
324	}
325	
326	function defaultBasis(unit: DisplayUnit): NutritionBasis {
327	  const d = unitDim(unit);
328	  return d === 'volume' ? '100ml' : d === 'count' ? 'unit' : '100g';
329	}
