60	  const [readingLabel, setReadingLabel] = useState(false);
61	  const lastCode = useRef<{ gtin: string; at: number } | null>(null);
62	
63	  async function lookup(code: ScannedCode) {
64	    const now = Date.now();
65	    if (lastCode.current?.gtin === code.gtin && now - lastCode.current.at < SAME_CODE_WINDOW_MS) return;
66	    lastCode.current = { gtin: code.gtin, at: now };
67	    setStep({ kind: 'looking' });
68	    try {
69	      // lookupCode, not gtin: it keeps an EAN-8 as 8 digits for the providers.
70	      const r = await scanApi.lookup(code.lookupCode);
71	      if (r.status === 'found') setStep({ kind: 'found', product: r.product });
72	      else if (r.status === 'not_found') setStep({ kind: 'not_found', gtin: r.gtin });
73	      else setStep({ kind: 'scan', notice: "That barcode doesn't look valid" });
74	    } catch (e) {
75	      setStep({ kind: 'scan', notice: e instanceof Error ? e.message : 'Could not look up that barcode.' });
