122	          />
123	        </>
124	      )}
125	
126	      {step.kind === 'not_found' && (
127	        <Card>
128	          <h2 className="font-display text-xl font-semibold">We couldn&apos;t find this product.</h2>
129	          <div className="mt-4 flex flex-wrap gap-3">
130	            <Button onClick={() => setStep({ kind: 'label', gtin: step.gtin })}>Take photo of label</Button>
131	            <Button variant="secondary" onClick={() => setStep({ kind: 'manual', gtin: step.gtin })}>
132	              Enter manually
