3	import { useEffect, useRef, useState } from 'react';
4	import { Button } from '@/components/ui';
5	import { normalizeBarcode, type BarcodeResult } from '@/lib/gtin';
6	import { getDetector } from './detector';
7	import { asBarcodeFormat, createReadConfirmer } from './pure';
8	
9	// SPEC F2 scanner. Load through next/dynamic with ssr:false. The typed input is always visible, so
10	// the flow works with no camera at all.
11	
12	export type ScannedCode = Extract<BarcodeResult, { ok: true }>;
13	
14	const SCAN_INTERVAL_MS = 150;
15	const INVALID = "That barcode doesn't look valid";
16	
17	type TorchCapabilities = MediaTrackCapabilities & { torch?: boolean };
18	
19	function cameraError(err: unknown): string {
20	  const name = err instanceof DOMException ? err.name : '';
21	  if (name === 'NotAllowedError') return 'Camera access is blocked. Allow it in your browser, or type the barcode below.';
22	  if (name === 'NotFoundError' || name === 'OverconstrainedError') return 'No camera found. Type the barcode below, or use a photo.';
23	  return "The camera isn't available. Type the barcode below, or use a photo.";
24	}
25	
26	export function BarcodeScanner({ onCode, notice }: { onCode: (code: ScannedCode) => void; notice?: string | null }) {
27	  const videoRef = useRef<HTMLVideoElement>(null);
28	  const trackRef = useRef<MediaStreamTrack | null>(null);
29	  const onCodeRef = useRef(onCode);
30	  const [deviceId, setDeviceId] = useState<string | null>(null);
31	  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
32	  const [cameraMessage, setCameraMessage] = useState<string | null>(null);
33	  const [torch, setTorch] = useState<{ available: boolean; on: boolean }>({ available: false, on: false });
34	  const [typed, setTyped] = useState('');
35	  const [message, setMessage] = useState<string | null>(null);
36	  const [reading, setReading] = useState(false);
37	
38	  useEffect(() => {
39	    onCodeRef.current = onCode;
40	  }, [onCode]);
41	
42	  useEffect(() => {
43	    let cancelled = false;
44	    let stream: MediaStream | null = null;
45	    let timer: ReturnType<typeof setTimeout> | undefined;
46	    const video = videoRef.current;
47	
48	    async function start() {
49	      try {
50	        if (!navigator.mediaDevices?.getUserMedia) throw new Error('no camera API');
51	        const size = { width: { ideal: 1280 }, height: { ideal: 720 } };
52	        const s = await navigator.mediaDevices.getUserMedia({
53	          audio: false,
54	          video: deviceId ? { deviceId: { exact: deviceId }, ...size } : { facingMode: { ideal: 'environment' }, ...size },
55	        });
56	        if (cancelled || !video) {
57	          s.getTracks().forEach((t) => t.stop());
58	          return;
59	        }
60	        stream = s;
61	        video.srcObject = s;
62	        await video.play();
63	        if (cancelled) return;
64	
65	        setCameraMessage(null);
66	        const track = s.getVideoTracks()[0] ?? null;
67	        trackRef.current = track;
68	        setTorch({ available: Boolean((track?.getCapabilities?.() as TorchCapabilities | undefined)?.torch), on: false });
69	        // Device labels are only readable once permission has been granted.
70	        const all = await navigator.mediaDevices.enumerateDevices();
71	        if (!cancelled) setDevices(all.filter((d) => d.kind === 'videoinput'));
72	
73	        const detector = await getDetector();
74	        const confirmRead = createReadConfirmer(2);
75	        const tick = async () => {
76	          if (cancelled) return;
77	          try {
78	            if (video.readyState >= 2) {
79	              const codes = await detector.detect(video);
80	              if (cancelled) return;
81	              for (const code of codes) {
82	                // A failed check digit here is a misread: keep scanning without bothering the user.
83	                const result = normalizeBarcode(code.rawValue, asBarcodeFormat(code.format));
84	                if (result.ok && confirmRead(code.rawValue)) {
85	                  onCodeRef.current(result);
86	                  return;
87	                }
88	              }
89	            }
90	          } catch {
91	            // A frame that can't be decoded is not an error; try the next one.
92	          }
93	          timer = setTimeout(() => void tick(), SCAN_INTERVAL_MS);
94	        };
95	        void tick();
96	      } catch (err) {
97	        if (!cancelled) setCameraMessage(cameraError(err));
98	      }
99	    }
100	
101	    void start();
102	    return () => {
103	      cancelled = true;
104	      clearTimeout(timer);
105	      stream?.getTracks().forEach((t) => t.stop());
106	      trackRef.current = null;
107	      if (video) video.srcObject = null;
108	    };
109	  }, [deviceId]);
110	
111	  async function toggleTorch() {
112	    const next = !torch.on;
113	    try {
114	      await trackRef.current?.applyConstraints({ advanced: [{ torch: next } as MediaTrackConstraintSet] });
115	      setTorch((t) => ({ ...t, on: next }));
116	    } catch {
117	      setTorch((t) => ({ ...t, available: false }));
118	    }
119	  }
120	
121	  function submitTyped(e: React.FormEvent) {
122	    e.preventDefault();
123	    if (typed.trim() === '') return;
124	    const result = normalizeBarcode(typed);
125	    if (result.ok) onCode(result);
126	    else setMessage(INVALID);
127	  }
128	
129	  async function readPhoto(file: File) {
130	    setMessage(null);
131	    setReading(true);
132	    try {
133	      const bitmap = await createImageBitmap(file);
134	      const detector = await getDetector();
135	      const codes = await detector.detect(bitmap);
136	      bitmap.close();
137	      if (codes.length === 0) return setMessage('No barcode found in that photo. Try again closer up, or type it below.');
138	      const result = normalizeBarcode(codes[0].rawValue, asBarcodeFormat(codes[0].format));
139	      if (result.ok) onCode(result);
140	      else setMessage(INVALID);
141	    } catch {
142	      setMessage("We couldn't read that photo. Try again, or type the barcode below.");
143	    } finally {
144	      setReading(false);
145	    }
146	  }
147	
148	  const shown = message ?? notice ?? null;
149	
150	  return (
151	    <div className="grid gap-4">
152	      <div className="relative aspect-video w-full overflow-hidden rounded-2xl bg-ink">
153	        <video ref={videoRef} className="h-full w-full object-cover" playsInline muted aria-label="Camera preview for scanning a barcode" />
154	        {cameraMessage ? (
155	          <p className="absolute inset-0 grid place-items-center p-6 text-center text-sm text-white">{cameraMessage}</p>
156	        ) : (
157	          <div aria-hidden className="pointer-events-none absolute inset-x-8 top-1/2 h-24 -translate-y-1/2 rounded-xl border-2 border-white/70" />
158	        )}
159	      </div>
160	
161	      {(devices.length > 1 || torch.available) && (
162	        <div className="flex flex-wrap items-center gap-3">
163	          {devices.length > 1 && (
164	            <label className="flex items-center gap-2 text-sm">
165	              Camera
166	              <select
167	                className="min-h-11 max-w-60 rounded-xl border border-line bg-surface px-3"
168	                value={deviceId ?? ''}
169	                onChange={(e) => setDeviceId(e.target.value || null)}
170	              >
171	                <option value="">Default</option>
172	                {devices.map((d, i) => (
173	                  <option key={d.deviceId || i} value={d.deviceId}>
174	                    {d.label || `Camera ${i + 1}`}
175	                  </option>
176	                ))}
177	              </select>
178	            </label>
179	          )}
180	          {torch.available && (
181	            <Button variant="secondary" aria-pressed={torch.on} onClick={() => void toggleTorch()}>
182	              {torch.on ? 'Torch off' : 'Torch on'}
183	            </Button>
184	          )}
185	        </div>
186	      )}
187	
188	      <form onSubmit={submitTyped} className="flex flex-wrap items-end gap-3">
189	        <label className="grid min-w-52 flex-1 gap-1 text-sm font-semibold">
190	          Type barcode
191	          <input
192	            className="min-h-11 w-full rounded-xl border border-line bg-surface px-3 text-ink"
193	            inputMode="numeric"
194	            autoComplete="off"
195	            value={typed}
196	            onChange={(e) => {
197	              setTyped(e.target.value);
198	              setMessage(null);
199	            }}
200	          />
201	        </label>
202	        <Button type="submit">Look up</Button>
203	      </form>
204	
205	      <label className="text-sm">
206	        <span className="font-semibold text-accent underline">{reading ? 'Reading photo…' : 'Use a photo of the barcode instead'}</span>
207	        <input
208	          type="file"
209	          accept="image/*"
210	          capture="environment"
211	          className="sr-only"
212	          disabled={reading}
213	          onChange={(e) => {
214	            const file = e.target.files?.[0];
215	            e.target.value = '';
216	            if (file) void readPhoto(file);
217	          }}
218	        />
219	      </label>
220	
221	      {shown && (
222	        <p role="alert" className="rounded-xl bg-danger-soft px-3 py-2 text-sm text-danger">
223	          {shown}
224	        </p>
225	      )}
226	    </div>
227	  );
228	}
