93	export async function logMeal(user: { id: string; tz: string }, input: ManualMealRequest): Promise<MealLog> {
94	  const at = resolveEatenAt(input.eatenAt);
95	  const localDate = todayInTz(user.tz, at);
96	
97	  return sql.begin(async (tx) => {
98	    let meal: NewMeal;
99	    if (input.kind === 'quick_add') {
100	      meal = {
101	        source: 'manual',
102	        label: input.label,
103	        pantryItemId: null,
104	        kcal: input.kcal,
105	        proteinG: input.proteinG,
106	        carbsG: input.carbsG ?? null,
107	        fatG: input.fatG ?? null,
108	      };
109	    } else if (input.kind === 'pantry_item') {
110	      const [row] = await tx<PantryItemRow[]>`SELECT * FROM pantry_items WHERE id = ${input.pantryItemId} AND user_id = ${user.id} FOR UPDATE`;
111	      if (!row) throw new NotFoundError('Pantry item not found');
112	      const item = rowToPantryItem(row, user.tz);
113	      const source = { basis: item.nutritionBasis, nutrition: item.nutrition, stockDim: item.dim, gramsPerUnit: item.gramsPerUnit, densityGPerMl: item.densityGPerMl };
114	      meal = {
115	        ...checkedNutrition(nutritionForAmount(source, input.amount, input.unit)),
116	        source: 'pantry_item',
117	        label: `${item.name} (${trimNumber(input.amount)} ${input.unit})`,
118	        pantryItemId: item.id,
119	      };
120	
121	      if (input.deductFromPantry) {
122	        const wanted = amountInStock(source, input.amount, input.unit);
123	        if (wanted === null) throw new UnprocessableError(amountError('no_conversion'));
124	        // Clamped like finish-cooking: eating more than the recorded stock empties it.
125	        const take = Math.round(Math.min(item.quantityBase, wanted) * 1000) / 1000;
126	        if (take > 0) {
127	          await tx`UPDATE pantry_items SET quantity_base = quantity_base - ${take}, updated_at = now() WHERE id = ${item.id}`;
128	          await tx`INSERT INTO pantry_events (user_id, pantry_item_id, kind, delta_base) VALUES (${user.id}, ${item.id}, 'eat_deduct', ${-take})`;
129	        }
130	      }
131	    } else {
132	      const code = normalizeGtin(input.gtin);
133	      const cached = code.ok ? await getCachedProduct(code.gtin) : null;
134	      if (!cached) throw new NotFoundError('Product not found. Scan it again.');
135	      const { product } = cached;
136	      const source = { basis: product.basis, nutrition: product.per100, stockDim: null, gramsPerUnit: null, densityGPerMl: null };
137	      meal = {
138	        ...checkedNutrition(nutritionForAmount(source, input.amount, input.unit)),
139	        source: 'barcode',
140	        label: `${product.name} (${trimNumber(input.amount)} ${input.unit})`,
141	        pantryItemId: null,
142	      };
143	    }
144	
145	    const [row] = await tx<MealRow[]>`
146	      INSERT INTO meal_logs (eaten_at, user_id, local_date, source, pantry_item_id, label, kcal, protein_g, carbs_g, fat_g)
147	      VALUES (${at.toISOString()}, ${user.id}, ${localDate}, ${meal.source}, ${meal.pantryItemId}, ${meal.label},
148	              ${meal.kcal}, ${meal.proteinG}, ${meal.carbsG}, ${meal.fatG})
149	      RETURNING *`;
150	    return rowToMeal(row);
151	  });
152	}
