196	/** The last `days` days ending today, oldest first, with empty days filled in as zeros. */
197	export async function getHistory(user: { id: string; tz: string }, days: number): Promise<DailyTotals[]> {
198	  const today = todayInTz(user.tz);
199	  const first = addDays(today, -(days - 1));
200	  const afterLast = addDays(today, 1);
201	  const [rows, profile] = await Promise.all([
202	    sql<{ date: string; kcal: number | null; protein_g: number | null; carbs_g: number | null; fat_g: number | null; entries: number }[]>`
203	      SELECT (day AT TIME ZONE ${AGGREGATE_TZ})::date AS date, kcal, protein_g, carbs_g, fat_g, entries
204	      FROM daily_nutrition
205	      WHERE user_id = ${user.id}
206	        AND day >= (${first}::date)::timestamp AT TIME ZONE ${AGGREGATE_TZ}
207	        AND day < (${afterLast}::date)::timestamp AT TIME ZONE ${AGGREGATE_TZ}`,
208	    getProfile(user.id),
209	  ]);
210	  const byDate = new Map(rows.map((r) => [r.date, r]));
211	  return Array.from({ length: days }, (_, i) => {
212	    const date = addDays(first, i);
213	    const r = byDate.get(date);
214	    return {
215	      date,
216	      kcal: r?.kcal ?? 0,
217	      proteinG: r?.protein_g ?? 0,
218	      carbsG: r?.carbs_g ?? 0,
219	      fatG: r?.fat_g ?? 0,
220	      entries: r?.entries ?? 0,
221	      kcalGoal: profile.dailyKcalGoal,
222	      proteinGoalG: profile.dailyProteinGoalG,
223	    };
224	  });
225	}
