200	    `;
201	    if (!cur) throw new NotFoundError('Pantry item not found');
202	
203	    const set: Record<string, unknown> = {};
204	    const oldBase = Number(cur.quantity_base);
205	    let newBase = oldBase;
206	
207	    // Quantity / unit. A unit change must stay in the item's dimension (base units never change).
208	    const unit = (input.displayUnit ?? cur.display_unit) as DisplayUnit;
209	    if (input.displayUnit !== undefined) {
