import { readFileSync, writeFileSync } from 'node:fs';

// Validate every patch first, then write, so a mismatch leaves the tree untouched.
const out = new Map();
function patch(file, pairs) {
  let s = out.get(file)?.text ?? readFileSync(file, 'utf8');
  const crlf = out.get(file)?.crlf ?? s.includes('
');
  if (crlf) s = s.replace(/
/g, '
');
  for (const [a, b] of pairs) {
    const n = s.split(a).length - 1;
    if (n !== 1) throw new Error(`${file}: expected 1 match, got ${n}: ${a.slice(0, 70)}`);
    s = s.replace(a, () => b);
  }
  out.set(file, { text: s, crlf });
}

